def fibonacci(n):
    if n <= 0:
        return []
    elif n == 1:
        return [0]
    elif n == 2:
        return [0, 1]
    else:
        a, b = 0, 1
        result = [a, b]
        while len(result) < n:
            a, b = b, a + b
            result.append(b)
        return result

