def sqrt(x):
    if x < 0:
        return None
    elif x == 0 or x == 1:
        return x
    else:
        return x ** (1/2)

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True
